mapper.select:
SELECT s.*, u.real_name, u.username, c.class_name FROM students s LEFT JOIN users u ON s.user_id = u.id LEFT JOIN classes c ON s.class_id = c.id
AND s.student_no LIKE CONCAT('%', #{studentNo}, '%')
AND u.real_name LIKE CONCAT('%', #{name}, '%')
AND s.class_id = #{classId}
LIMIT #{offset}, #{limit}

